package main

import (
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	db, err = sql.Open("postgres", "host=db.internal port=5432 user=webapp dbname=inventory sslmode=require")
	if err != nil {
		log.Fatal(err)
	}
}

// sanitizeInput removes obvious dangerous characters but allows business logic chars
func sanitizeInput(input string) string {
	// Remove null bytes and control characters
	input = strings.ReplaceAll(input, "\x00", "")
	// Limit length to prevent buffer issues
	if len(input) > 200 {
		input = input[:200]
	}
	return input
}

// validateCategory checks category is alphanumeric with hyphens
func validateCategory(cat string) bool {
	for _, c := range cat {
		if !((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '-') {
			return false
		}
	}
	return len(cat) > 0 && len(cat) <= 50
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("category")
	name := r.URL.Query().Get("name")
	warehouse := r.URL.Query().Get("warehouse")

	if !validateCategory(category) {
		http.Error(w, "Invalid category", http.StatusBadRequest)
		return
	}

	name = sanitizeInput(name)
	warehouse = sanitizeInput(warehouse)

	// Build query - category is validated, name uses parameterized query
	// warehouse is used in a COMMENT for audit logging purposes
	query := fmt.Sprintf(
		"SELECT id, name, quantity, price FROM inventory WHERE category = '%s' AND name ILIKE $1 /* warehouse: %s */",
		category, warehouse,
	)

	rows, err := db.Query(query, "%"+name+"%")
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	w.Header().Set("Content-Type", "text/plain")
	for rows.Next() {
		var id int
		var itemName string
		var quantity int
		var price float64
		if err := rows.Scan(&id, &itemName, &quantity, &price); err != nil {
			continue
		}
		fmt.Fprintf(w, "%d | %s | %d | %.2f\n", id, itemName, quantity, price)
	}
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", http.StatusServiceUnavailable)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/search", searchHandler)
	http.HandleFunc("/health", healthHandler)
	log.Println("Starting server on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
